window.AUTH=window.AUTH||{};window.AUTH["10-1062"]={"d":"10-1062","id":"2011/10-1062","n":"Sackett v. EPA","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the respondents","date":"2011-11-23","url":"https://www.justice.gov/osg/media/196811/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/sackett-v-environmental-protection-agency-0","n":93}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep566/usrep566120/usrep566120.pdf","tr":true,"items":[{"t":"case","label":"AT&T v. EEOC","cite":"270 F.3d 973","y":2001,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/270/973/","by":{"0":"21, 22, 27, 37"}},{"t":"case","label":"Abbott Labs. v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"ar":3,"sum":"The Court found that congress did not intend to forbid pre-enforcement review of regulations like the \"every time\" rule. The legislature designed the statute's specific review provisions to provide additional remedies for parties in Abbott Laboratories' position, not to cut down traditional channels of review. The Court remanded the case to the court of appeals.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Air Brake Sys. Inc. v. Mineta","cite":"357 F.3d 632","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/357/632/","by":{"0":"20"}},{"t":"case","label":"Air Cal. v. United States Dep’t of Transp.","cite":"654 F.2d 616","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/654/616/","by":{"0":"20"}},{"t":"case","label":"Alaska Dep’t of Envtl. Conservation v. EPA","cite":"244 F.3d 748","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/244/748/","by":{"0":"33"}},{"t":"case","label":"American Fed’n of Gov’t Employees, AFL-CIO v. O’Connor","cite":"747 F.2d 748","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/747/748/","by":{"0":"21"}},{"t":"case","label":"Baccarat Fremont Developers, LLC v. United States Army Corps of Eng’rs","cite":"425 F.3d 1150","y":2005,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/425/1150/","by":{"0":"4, 53"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"op":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"0":"11, 24"}},{"t":"case","label":"Block v. Community Nutrition Inst.","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"op":2,"sum":"The individual consumers may not obtain judicial review of the milk market orders in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 34, 35, 39"}},{"t":"case","label":"City of San Diego v. Whitman","cite":"242 F.3d 1097","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/242/1097/","by":{"0":"21"}},{"t":"case","label":"Connecticut v. Doehr","cite":"501 U.S. 1","y":1991,"id":"1990/90-143","sc":1,"sum":"The judgment is affirmed. 898,F. 2d 852, affirmed. JUSTICE WHITE delivered the opinion of the Court with respect to Parts 1, 11, and III, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Dietary Supplement Coal., Inc. v. Sullivan","cite":"978 F.2d 560","y":1992,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/978/560/","by":{"0":"19"}},{"t":"case","label":"EPA v. California","cite":"426 U.S. 200","y":1976,"id":"1975/74-1435","sc":1,"sum":"While federal installations discharging water pollutants are obliged, under § 313 of the Federal Water Pollution Control Act Amendments of 1972 (Amendments), to comply to the same extent as nonfederal facilities with state \"requirements respecting control and abatement of pollution,\" obtaining a permit from a State with a federally approved permit program is not among such requirements. Federal installations are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"52"}},{"t":"case","label":"FDIC v. Mallen","cite":"486 U.S. 230","y":1988,"id":"1987/87-82","sc":1,"sum":"Title 12 U. S. C. § 1818(g)(1) authorizes the Federal Deposit Insurance Corporation (FDIC) to suspend from office an indicted official of a federally insured bank if his continued service poses a threat to the interests of the bank's depositors or threatens to impair public confidence in the bank. Section 1818(g)(3) entitles a suspended official to a hearing before the FDIC within 30 days of his written request, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"FTC v. Standard Oil Co. of Cal.","cite":"449 U.S. 232","y":1980,"id":"1980/79-900","sc":1,"sum":"The FTC's issuance of its complaint was not \"final agency action\" under § 10 (c) of the APA and hence was not judicially reviewable before the conclusion of the administrative adjudication.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11, 25, 27"}},{"t":"case","label":"Fairbanks N. Star Borough v. United States Army Corps of Eng’rs","cite":"543 F.3d 586","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/543/586/","by":{"0":"28, 53"}},{"t":"case","label":"FEC v. Williams","cite":"104 F.3d 237","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/104/237/","by":{"0":"8"}},{"t":"case","label":"Free Enter. Fund v. Public Co. Accounting Oversight Board","cite":"130 S. Ct. 3138","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Heckler v. Chaney","cite":"470 U.S. 821","y":1985,"id":"1984/83-1878","sc":1,"sum":"They are presumptively unreviewable. Refusals of administrative agencies to exercise enforcement authority involve a complicated balancing of factors, including agency allocation of scarce resources, which are not suitable for judicial review. Thus, they are presumptively \"committed to agency discretion by law\" under Section 701(a)(2).","sumSrc":"Oyez","by":{"0":"36, 37"}},{"t":"case","label":"Hoffman Group, Inc. v. EPA","cite":"902 F.2d 567","y":1990,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/902/567/","by":{"0":"36, 38"}},{"t":"case","label":"Lloyd A. Fry Roofing Co. v. EPA","cite":"554 F.2d 885","y":1977,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/554/885/","by":{"0":"50"}},{"t":"case","label":"Massachusetts v. EPA","cite":"549 U.S. 497","y":2007,"id":"2006/05-1120","sc":1,"sum":"The Court ruled that states could sue the EPA for potential damage to their territory caused by global warming, and that the Clean Air Act imposes a duty upon the EPA to regulate the emissions of carbon dioxide and other gases that contribute to global warming.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"McNary v. Haitian Refugee Ctr., Inc.","cite":"498 U.S. 479","y":1991,"id":"1990/89-1332","sc":1,"sum":"The District Court had federal-question jurisdiction to hear respondents' constitutional and statutory challenges to the INS procedures.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43, 44"}},{"t":"case","label":"Morris v. Gressette","cite":"432 U.S. 491","y":1977,"id":"1976/75-1583","sc":1,"sum":"Section 5 of the Voting Rights Act of 1965 establishes two alternative methods by which States subject to the Act can obtain federal preclearance review of a change in their voting laws: (1) the State may file a declaratory judgment action in the District Court for the District of Columbia and subsequently may implement such change if that court declares that the change has no racially discriminatory purpose or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"NLRB v. United Food & Commercial Workers Union Local 23","cite":"484 U.S. 112","y":1987,"id":"1987/86-594","sc":1,"sum":"National Labor Relations Board regulations implementing the unfair labor practice provisions of the National Labor Relations Act (NLRA or Act) provide that, after one of the Board's regional directors has filed a complaint but before a hearing is held thereon, the director may enter into either a formal or an informal settlement. The regulations allow a nonconsenting party to appeal a formal settlement to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"National Automatic Laundry & Cleaning Council v. Shultz","cite":"443 F.2d 689","y":1971,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/443/689/","by":{"0":"23"}},{"t":"case","label":"National Park Hospitality Ass’n v. Department of the Interior","cite":"538 U.S. 803","y":2003,"id":"2002/02-196","sc":1,"sum":"The Court held that the controversy was not yet ripe for judicial resolution.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Ohio Forestry Ass’n v. Sierra Club","cite":"523 U.S. 726","y":1998,"id":"1997/97-16","sc":1,"sum":"The Court held that the controversy is not yet ripe for judicial review.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Phillips Petroleum Co. v. Lujan","cite":"963 F.2d 1380","y":1992,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/963/1380/","op":1,"by":{"0":"25"}},{"t":"case","label":"Precon Dev. Corp. v. United States Army Corps of Eng’rs","cite":"633 F.3d 278","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/633/278/","by":{"0":"51, 52"}},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"op":2,"ar":2,"sum":"The plurality rejected the argument that only actually-navigable waters can be regulated by the Clean Water Act, but also held that the word \"navigable\" in the Act cannot be divested of all meaning. The plurality held that the definitional term \"waters of the United States\" can only refer to \"relatively permanent, standing or flowing bodies of water,\" not \"occasional,\" \"intermittent,\" or \"ephemeral\" flows.","sumSrc":"Oyez","by":{"0":"2, 8"}},{"t":"case","label":"Reisman v. Caplin","cite":"375 U.S. 440","y":1964,"id":"1963/119","sc":1,"sum":"Petitioners have an adequate remedy at law and the complaint is properly dismissed for want of equity.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48, 52"}},{"t":"case","label":"Reliable Automatic Sprinkler Co. v. CPSC","cite":"324 F.3d 726","y":2003,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/324/726/","by":{"0":"20, 22, 25, 29"}},{"t":"case","label":"Shalala v. Illinois Council on Long Term Care, Inc.","cite":"529 U.S. 1","y":2000,"id":"1999/98-1109","sc":1,"sum":"The Court held that the Medicare Act barred federal-question jurisdiction of the Council's challenges to the validity of various Medicare regulations. The Court concluded that the Council must proceed instead through the special review channel that the Medicare statutes create.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Shaughnessy v. Pedreiro","cite":"349 U.S. 48","y":1955,"id":"scdb/1954-069","sc":1,"sum":"1. Under § 10 of the Administrative Procedure Act, an alien whose deportation has been ordered administratively under the Immigration and Nationality Act of 1952 may obtain a judicial review of such order by an action in a federal district court for a declaratory judgment and injunctive relief.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Southern Pines Assocs. v. United States","cite":"912 F.2d 713","y":1999,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/912/713/","op":1,"by":{"0":"39"}},{"t":"case","label":"Thunder Basin Coal Co. v. Reich","cite":"510 U.S. 200","y":1994,"id":"1993/92-896","sc":1,"sum":"Petitioner mine operator's nonunion work force designated two employees of the United Mine Workers of America (UMWA) to serve as miners' representatives under 30 U. S. C. §813(f). Claiming that the designations compromised its rights under the National Labor Relations Act (NLRA), petitioner refused to post information about the representatives as required by a regulation issued by the Department of Labor's Mine …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"United States v. Bay-Houston Towing Co.","cite":"197 F. Supp. 2d 788","y":2002,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/197/788/","by":{"0":"50"}},{"t":"case","label":"United States v. Brace","cite":"41 F.3d 117","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/41/117/","by":{"0":"15"}},{"t":"case","label":"United States v. Deaton","cite":"332 F.3d 698","y":2003,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/332/698/","by":{"0":"14"}},{"t":"case","label":"United States v. Erika, Inc.","cite":"456 U.S. 201","y":1982,"id":"1981/80-1594","sc":1,"op":1,"sum":"The Court of Claims has no jurisdiction to review determinations by private insurance carriers of the amount of benefits payable under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"op":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34, 35, 38"}},{"t":"case","label":"United States v. Riverside Bayview Homes, Inc.","cite":"474 U.S. 121","y":1985,"id":"1985/84-701","sc":1,"op":1,"ar":1,"sum":"The Clean Water Act prohibits any discharge of dredged or fill materials into \"navigable waters\"-defined as the \"waters of the United States\"unless authorized by a permit issued by the Army Corps of Engineers (Corps). Construing the Act to cover all \"freshwater wetlands\" that are adjacent to other covered waters, the Corps issued a regulation defining such wetlands as \"those areas that are inundated or saturated by …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2"}},{"t":"case","label":"United States v. Scruggs","cite":"2009 WL 500608","y":2009,"court":"S.D. Tex. Feb. 26","sum":"Concluding that “a severe penalty is not appropriate” based on analysis of the defendant’s ability to pay, the lack of economic benefit from the violation, and the relatively low severity of the violation; awarding $65,000 when the statutory maximum exposure was $1.3 million.","sumSrc":"brief:0","by":{"0":"30, 50"}},{"t":"case","label":"United States v. United Mine Workers of Am.","cite":"330 U.S. 258","y":1947,"id":"scdb/1946-060","sc":1,"sum":"1. Neither the Norris-LaGuardia Act, 47 Stat. 70, nor § 20 of the Clayton Act, 38 Stat. 738, deprives a federal district court of jurisdiction to issue a restraining order and preliminary injunction in a suit by the Government to prevent a union and its officers from precipitating a nation-wide strike in the bituminous coal mines pending judicial interpretation of a labor contract between the Government and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"USAA Fed. Sav. Bank v. McLaughlin","cite":"849 F.2d 1505","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/849/1505/","by":{"0":"21"}},{"t":"case","label":"Walker v. City of Birmingham","cite":"388 U.S. 307","y":1967,"id":"1966/249","sc":1,"sum":"The Court upheld the arrests since Walker failed to use proper judicial procedures to test the injunction's validity. Even though, Justice Stewart admitted, the injunction seemed broad and vague, and the marchers may not have enjoyed due process when applying for the permit originally, simply disobeying the injunction was illegitimate as \"no man can be judge in his own case . . . however righteous his motives.\".","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"West Va. Highlands Conservancy, Inc. v. Huffman","cite":"625 F.3d 159","y":2010,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/625/159/","sum":"Noting that Congress considered the costs of a permitting system before deciding that “a permitting scheme is the crucial instrument for protecting natural resources”.","sumSrc":"brief:0","by":{"0":"53"}},{"t":"case","label":"Wilson v. Pena","cite":"79 F.3d 154","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/79/154/","by":{"0":"21"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"44, 47"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"0":"4"}},{"t":"usc","label":"5 U.S.C. § 559","url":"https://www.law.cornell.edu/uscode/text/5/559","by":{"0":"35"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(1)"],"by":{"0":"34"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","stext":{"head":"§704. Actions reviewable","paras":[[0,"Agency action made reviewable by statute and final agency action for which there is no other adequate remedy in a court are subject to judicial review. A preliminary, procedural, or intermediate agency action or ruling not directly reviewable is subject to review on the review of the final agency action. Except as otherwise expressly required by statute, agency action otherwise final is final for the purposes of this section whether or not there has been presented or determined an application for a declaratory order, for any form of reconsideration, or, unless the agency otherwise requires by rule and provides that the action meanwhile is inoperative, for an appeal to superior agency authority."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/704?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§704. Actions reviewable","tname":"Government Organization and Employees","by":{"0":"11, 24, 34, 51"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"0":"8, 37"}},{"t":"usc","label":"42 U.S.C. § 7401","url":"https://www.law.cornell.edu/uscode/text/42/7401","by":{"0":"40"}},{"t":"usc","label":"42 U.S.C. § 7413","url":"https://www.law.cornell.edu/uscode/text/42/7413","subs":["(a)(5)","(b)(3)"],"by":{"0":"33, 33"}},{"t":"usc","label":"42 U.S.C. § 7477","url":"https://www.law.cornell.edu/uscode/text/42/7477","by":{"0":"33"}},{"t":"usc","label":"42 U.S.C. § 7603","url":"https://www.law.cornell.edu/uscode/text/42/7603","by":{"0":"41"}},{"t":"usc","label":"42 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/42/7607","subs":["(b)(1)"],"by":{"0":"41"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","subs":["(a)"],"by":{"0":"2, 2"}},{"t":"usc","label":"33 U.S.C. § 1311","url":"https://www.law.cornell.edu/uscode/text/33/1311","subs":["(a)"],"stext":{"head":"§1311. Effluent limitations","paras":[[0,"(a) Illegality of pollutant discharges except in compliance with law"],[0,"Except as in compliance with this section and sections 1312, 1316, 1317, 1328, 1342, and 1344 of this title, the discharge of any pollutant by any person shall be unlawful."],[0,"(b) Timetable for achievement of objectives"],[0,"In order to carry out the objective of this chapter there shall be achieved—"],[1,"(1)(A) not later than July 1, 1977, effluent limitations for point sources, other than publicly owned treatment works, (i) which shall require the application of the best practicable control technology currently available as defined by the Administrator pursuant to section 1314(b) of this title, or (ii) in the case of a discharge into a publicly owned treatment works which meets the requirements of subparagraph (B) of this paragraph, which shall require compliance with any applicable pretreatment requirements and any requirements under section 1317 of this title; and"],[1,"(B) for publicly owned treatment works in existence on July 1, 1977, or approved pursuant to section 1283 of this title prior to June 30, 1974 (for which construction must be completed within four years of approval), effluent limitations based upon secondary treatment as defined by the Administrator pursuant to section 1314(d)(1) of this title; or,"],[1,"(C) not later than July 1, 1977, any more stringent limitation, including those necessary to meet water quality standards, treatment standards, or schedules of compliance, established pursuant to any State law or regulations (under authority preserved by section 1370 of this title) or any other Federal law or regulation, or required to implement any applicable water quality standard established pursuant to this chapter."],[1,"(2)(A) for pollutants identified in subparagraphs (C), (D), and (F) of this paragraph, effluent limitations for categories and classes of point sources, other than publicly owned treatment works, which (i) shall require application of the best available technology economically achievable for such category or class, which will result in reasonable further progress toward the national goal of eliminating the discharge of all pollutants, as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(2) of this title, which such effluent limitations shall require the elimination of discharges of all pollutants if the Administrator finds, on the basis of information available to him (including information developed pursuant to section 1325 of this title), that such elimination is technologically and economically achievable for a category or class of point sources as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(2) of this title, or (ii) in the case of the introduction of a pollutant into a publicly owned treatment works which meets the requirements of subparagraph (B) of this paragraph, shall require compliance with any applicable pretreatment requirements and any other requirement under section 1317 of this title;"],[1,"(B) Repealed. Pub. L. 97–117, §21(b), Dec. 29, 1981, 95 Stat. 1632."],[1,"(C) with respect to all toxic pollutants referred to in table 1 of Committee Print Numbered 95–30 of the Committee on Public Works and Transportation of the House of Representatives compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989;"],[1,"(D) for all toxic pollutants listed under paragraph (1) of subsection (a) of section 1317 of this title which are not referred to in subparagraph (C) of this paragraph compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable, but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989;"],[1,"(E) as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989, compliance with effluent limitations for categories and classes of point sources, other than publicly owned treatment works, which in the case of pollutants identified pursuant to section 1314(a)(4) of this title shall require application of the best conventional pollutant control technology as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(4) of this title; and"],[1,"(F) for all pollutants (other than those subject to subparagraphs (C), (D), or (E) of this paragraph) compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable but in no case later than 3 years after the date such limitations are established, and in no case later than March 31, 1989."],[1,"(3)(A) for effluent limitations under paragraph (1)(A)(i) of this subsection promulgated after January 1, 1982, and requiring a level of control substantially greater or based on fundamentally different control technology than under permits for an industrial category issued before such date, compliance as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989; and"],[1,"(B) for any effluent limitation in accordance with paragraph (1)(A)(i), (2)(A)(i), or (2)(E) of this subsection established only on the basis of section 1342(a)(1) of this title in a permit issued after February 4, 1987, compliance as expeditiously as practicable but in no case later than three years after the date such limitations are established, and in no case later than March 31, 1989."],[0,"(c) Modification of timetable"],[0,"The Administrator may modify the requirements of subsection (b)(2)(A) of this section with respect to any point source for which a permit application is filed after July 1, 1977, upon a showing by the owner or operator of such point source satisfactory to the Administrator that such modified requirements (1) will represent the maximum use of technology within the economic capability of the owner or operator; and (2) will result in reasonable further progress toward the elimination of the discharge of pollutants."],[0,"(d) Review and revision of effluent limitations"],[0,"Any effluent limitation required by paragraph (2) of subsection (b) of this section shall be reviewed at least every five years and, if appropriate, revised pursuant to the procedure established under such paragraph."],[0,"(e) All point discharge source application of effluent limitations"],[0,"Effluent limitations established pursuant to this section or section 1312 of this title shall be applied to all point sources of discharge of pollutants in accordance with the provisions of this chapter."],[0,"(f) Illegality of discharge of radiological, chemical, or biological warfare agents, high-level radioactive waste, or medical waste"],[0,"Notwithstanding any other provisions of this chapter it shall be unlawful to discharge any radiological, chemical, or biological warfare agent, any high-level radioactive waste, or any medical waste, into the navigable waters."],[0,"(g) Modifications for certain nonconventional pollutants"],[0,"(1) General authority"],[1,"The Administrator, with the concurrence of the State, may modify the requirements of subsection (b)(2)(A) of this section with respect to the discharge from any point source of ammonia, chlorine, color, iron, and total phenols (4AAP) (when determined by the Administrator to be a pollutant covered by subsection (b)(2)(F)) and any other pollutant which the Administrator lists under paragraph (4) of this subsection."],[0,"(2) Requirements for granting modifications"],[1,"A modification under this subsection shall be granted only upon a showing by the owner or operator of a point source satisfactory to the Administrator that—"],[2,"(A) such modified requirements will result at a minimum in compliance with the requirements of subsection (b)(1)(A) or (C) of this section, whichever is applicable;"],[2,"(B) such modified requirements will not result in any additional requirements on any other point or nonpoint source; and"],[2,"(C) such modification will not interfere with the attainment or maintenance of that water quality which shall assure protection of public water supplies, and the protection and propagation of a balanced population of shellfish, fish, and wildlife, and allow recreational activities, in and on the water and such modification will not result in the discharge of pollutants in quantities which may reasonably be anticipated to pose an unacceptable risk to human health or the environment because of bioaccumulation, persistency in the environment, acute toxicity, chronic toxicity (including carcinogenicity, mutagenicity or teratogenicity), or synergistic propensities."],[0,"(3) Limitation on authority to apply for subsection (c) modification"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1311?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1311. Effluent limitations","tname":"Navigation and Navigable Waters","by":{"0":"2, 6"}},{"t":"usc","label":"33 U.S.C. § 1318","url":"https://www.law.cornell.edu/uscode/text/33/1318","subs":["(a)"],"by":{"0":"4, 46, 46"}},{"t":"usc","label":"33 U.S.C. § 1319","url":"https://www.law.cornell.edu/uscode/text/33/1319","subs":["(a)","(a)(3)","(b)","(c)","(d)","(g)","(g)(1)(A)","(g)(8)"],"stext":{"head":"§1319. Enforcement","paras":[[0,"(a) State enforcement; compliance orders"],[0,"(1) Whenever, on the basis of any information available to him, the Administrator finds that any person is in violation of any condition or limitation which implements section 1311, 1312, 1316, 1317, 1318, 1328, or 1345 of this title in a permit issued by a State under an approved permit program under section 1342 or 1344 of this title he shall proceed under his authority in paragraph (3) of this subsection or he shall notify the person in alleged violation and such State of such finding. If beyond the thirtieth day after the Administrator's notification the State has not commenced appropriate enforcement action, the Administrator shall issue an order requiring such person to comply with such condition or limitation or shall bring a civil action in accordance with subsection (b) of this section."],[0,"(2) Whenever, on the basis of information available to him, the Administrator finds that violations of permit conditions or limitations as set forth in paragraph (1) of this subsection are so widespread that such violations appear to result from a failure of the State to enforce such permit conditions or limitations effectively, he shall so notify the State. If the Administrator finds such failure extends beyond the thirtieth day after such notice, he shall give public notice of such finding. During the period beginning with such public notice and ending when such State satisfies the Administrator that it will enforce such conditions and limitations (hereafter referred to in this section as the period of \"federally assumed enforcement\"), except where an extension has been granted under paragraph (5)(B) of this subsection, the Administrator shall enforce any permit condition or limitation with respect to any person—"],[1,"(A) by issuing an order to comply with such condition or limitation, or"],[1,"(B) by bringing a civil action under subsection (b) of this section."],[0,"(3) Whenever on the basis of any information available to him the Administrator finds that any person is in violation of section 1311, 1312, 1316, 1317, 1318, 1322(p), 1328, or 1345 of this title, or is in violation of any permit condition or limitation implementing any of such sections in a permit issued under section 1342 of this title by him or by a State or in a permit issued under section 1344 of this title by a State, he shall issue an order requiring such person to comply with such section or requirement, or he shall bring a civil action in accordance with subsection (b) of this section."],[0,"(4) A copy of any order issued under this subsection shall be sent immediately by the Administrator to the State in which the violation occurs and other affected States. In any case in which an order under this subsection (or notice to a violator under paragraph (1) of this subsection) is issued to a corporation, a copy of such order (or notice) shall be served on any appropriate corporate officers. An order issued under this subsection relating to a violation of section 1318 of this title shall not take effect until the person to whom it is issued has had an opportunity to confer with the Administrator concerning the alleged violation."],[0,"(5)(A) Any order issued under this subsection shall be by personal service, shall state with reasonable specificity the nature of the violation, and shall specify a time for compliance not to exceed thirty days in the case of a violation of an interim compliance schedule or operation and maintenance requirement and not to exceed a time the Administrator determines to be reasonable in the case of a violation of a final deadline, taking into account the seriousness of the violation and any good faith efforts to comply with applicable requirements."],[0,"(B) The Administrator may, if he determines (i) that any person who is a violator of, or any person who is otherwise not in compliance with, the time requirements under this chapter or in any permit issued under this chapter, has acted in good faith, and has made a commitment (in the form of contracts or other securities) of necessary resources to achieve compliance by the earliest possible date after July 1, 1977, but not later than April 1, 1979; (ii) that any extension under this provision will not result in the imposition of any additional controls on any other point or nonpoint source; (iii) that an application for a permit under section 1342 of this title was filed for such person prior to December 31, 1974; and (iv) that the facilities necessary for compliance with such requirements are under construction, grant an extension of the date referred to in section 1311(b)(1)(A) of this title to a date which will achieve compliance at the earliest time possible but not later than April 1, 1979."],[0,"(6) Whenever, on the basis of information available to him, the Administrator finds (A) that any person is in violation of section 1311(b)(1)(A) or (C) of this title, (B) that such person cannot meet the requirements for a time extension under section 1311(i)(2) of this title, and (C) that the most expeditious and appropriate means of compliance with this chapter by such person is to discharge into a publicly owned treatment works, then, upon request of such person, the Administrator may issue an order requiring such person to comply with this chapter at the earliest date practicable, but not later than July 1, 1983, by discharging into a publicly owned treatment works if such works concur with such order. Such order shall include a schedule of compliance."],[0,"(b) Civil actions"],[0,"The Administrator is authorized to commence a civil action for appropriate relief, including a permanent or temporary injunction, for any violation for which he is authorized to issue a compliance order under subsection (a) of this section. Any action under this subsection may be brought in the district court of the United States for the district in which the defendant is located or resides or is doing business, and such court shall have jurisdiction to restrain such violation and to require compliance. Notice of the commencement of such action shall be given immediately to the appropriate State."],[0,"(c) Criminal penalties"],[0,"(1) Negligent violations"],[1,"Any person who—"],[2,"(A) negligently violates section 1311, 1312, 1316, 1317, 1318, 1321(b)(3), 1322(p), 1328, or 1345 of this title, or any permit condition or limitation implementing any of such sections in a permit issued under section 1342 of this title by the Administrator or by a State, or any requirement imposed in a pretreatment program approved under section 1342(a)(3) or 1342(b)(8) of this title or in a permit issued under section 1344 of this title by the Secretary of the Army or by a State; or"],[2,"(B) negligently introduces into a sewer system or into a publicly owned treatment works any pollutant or hazardous substance which such person knew or reasonably should have known could cause personal injury or property damage or, other than in compliance with all applicable Federal, State, or local requirements or permits, which causes such treatment works to violate any effluent limitation or condition in any permit issued to the treatment works under section 1342 of this title by the Administrator or a State;"],[1,"shall be punished by a fine of not less than $2,500 nor more than $25,000 per day of violation, or by imprisonment for not more than 1 year, or by both. If a conviction of a person is for a violation committed after a first conviction of such person under this paragraph, punishment shall be by a fine of not more than $50,000 per day of violation, or by imprisonment of not more than 2 years, or by both."],[0,"(2) Knowing violations"],[1,"Any person who—"],[2,"(A) knowingly violates section 1311, 1312, 1316, 1317, 1318, 1321(b)(3), 1322(p), 1328, or 1345 of this title, or any permit condition or limitation implementing any of such sections in a permit issued under section 1342 of this title by the Administrator or by a State, or any requirement imposed in a pretreatment program approved under section 1342(a)(3) or 1342(b)(8) of this title or in a permit issued under section 1344 of this title by the Secretary of the Army or by a State; or"],[2,"(B) knowingly introduces into a sewer system or into a publicly owned treatment works any pollutant or hazardous substance which such person knew or reasonably should have known could cause personal injury or property damage or, other than in compliance with all applicable Federal, State, or local requirements or permits, which causes such treatment works to violate any effluent limitation or condition in a permit issued to the treatment works under section 1342 of this title by the Administrator or a State;"],[1,"shall be punished by a fine of not less than $5,000 nor more than $50,000 per day of violation, or by imprisonment for not more than 3 years, or by both. If a conviction of a person is for a violation committed after a first conviction of such person under this paragraph, punishment shall be by a fine of not more than $100,000 per day of violation, or by imprisonment of not more than 6 years, or by both."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1319?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1319. Enforcement","tname":"Navigation and Navigable Waters","by":{"0":"4, 46, 5, 14, 28, 36, 38, 5, 14, 15, 38, 6, 16, passim, 5, 18, 18, 5, 18, 38"}},{"t":"usc","label":"33 U.S.C. § 1342","url":"https://www.law.cornell.edu/uscode/text/33/1342","by":{"0":"3"}},{"t":"usc","label":"33 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/33/1344","subs":["(a)","(b)","(c)","(e)(1)","(g)","(n)","(s)"],"stext":{"head":"§1344. Permits for dredged or fill material","paras":[[0,"(a) Discharge into navigable waters at specified disposal sites"],[0,"The Secretary may issue permits, after notice and opportunity for public hearings for the discharge of dredged or fill material into the navigable waters at specified disposal sites. Not later than the fifteenth day after the date an applicant submits all the information required to complete an application for a permit under this subsection, the Secretary shall publish the notice required by this subsection."],[0,"(b) Specification for disposal sites"],[0,"Subject to subsection (c) of this section, each such disposal site shall be specified for each such permit by the Secretary (1) through the application of guidelines developed by the Administrator, in conjunction with the Secretary, which guidelines shall be based upon criteria comparable to the criteria applicable to the territorial seas, the contiguous zone, and the ocean under section 1343(c) of this title, and (2) in any case where such guidelines under clause (1) alone would prohibit the specification of a site, through the application additionally of the economic impact of the site on navigation and anchorage."],[0,"(c) Denial or restriction of use of defined areas as disposal sites"],[0,"The Administrator is authorized to prohibit the specification (including the withdrawal of specification) of any defined area as a disposal site, and he is authorized to deny or restrict the use of any defined area for specification (including the withdrawal of specification) as a disposal site, whenever he determines, after notice and opportunity for public hearings, that the discharge of such materials into such area will have an unacceptable adverse effect on municipal water supplies, shellfish beds and fishery areas (including spawning and breeding areas), wildlife, or recreational areas. Before making such determination, the Administrator shall consult with the Secretary. The Administrator shall set forth in writing and make public his findings and his reasons for making any determination under this subsection."],[0,"(d) \"Secretary\" defined"],[0,"The term \"Secretary\" as used in this section means the Secretary of the Army, acting through the Chief of Engineers."],[0,"(e) General permits on State, regional, or nationwide basis"],[0,"(1) In carrying out his functions relating to the discharge of dredged or fill material under this section, the Secretary may, after notice and opportunity for public hearing, issue general permits on a State, regional, or nationwide basis for any category of activities involving discharges of dredged or fill material if the Secretary determines that the activities in such category are similar in nature, will cause only minimal adverse environmental effects when performed separately, and will have only minimal cumulative adverse effect on the environment. Any general permit issued under this subsection shall (A) be based on the guidelines described in subsection (b)(1) of this section, and (B) set forth the requirements and standards which shall apply to any activity authorized by such general permit."],[0,"(2) No general permit issued under this subsection shall be for a period of more than five years after the date of its issuance and such general permit may be revoked or modified by the Secretary if, after opportunity for public hearing, the Secretary determines that the activities authorized by such general permit have an adverse impact on the environment or such activities are more appropriately authorized by individual permits."],[0,"(f) Non-prohibited discharge of dredged or fill material"],[0,"(1) Except as provided in paragraph (2) of this subsection, the discharge of dredged or fill material—"],[1,"(A) from normal farming, silviculture, and ranching activities such as plowing, seeding, cultivating, minor drainage, harvesting for the production of food, fiber, and forest products, or upland soil and water conservation practices;"],[1,"(B) for the purpose of maintenance, including emergency reconstruction of recently damaged parts, of currently serviceable structures such as dikes, dams, levees, groins, riprap, breakwaters, causeways, and bridge abutments or approaches, and transportation structures;"],[1,"(C) for the purpose of construction or maintenance of farm or stock ponds or irrigation ditches, or the maintenance of drainage ditches;"],[1,"(D) for the purpose of construction of temporary sedimentation basins on a construction site which does not include placement of fill material into the navigable waters;"],[1,"(E) for the purpose of construction or maintenance of farm roads or forest roads, or temporary roads for moving mining equipment, where such roads are constructed and maintained, in accordance with best management practices, to assure that flow and circulation patterns and chemical and biological characteristics of the navigable waters are not impaired, that the reach of the navigable waters is not reduced, and that any adverse effect on the aquatic environment will be otherwise minimized;"],[1,"(F) resulting from any activity with respect to which a State has an approved program under section 1288(b)(4) of this title which meets the requirements of subparagraphs (B) and (C) of such section,"],[0,"is not prohibited by or otherwise subject to regulation under this section or section 1311(a) or 1342 of this title (except for effluent standards or prohibitions under section 1317 of this title)."],[0,"(2) Any discharge of dredged or fill material into the navigable waters incidental to any activity having as its purpose bringing an area of the navigable waters into a use to which it was not previously subject, where the flow or circulation of navigable waters may be impaired or the reach of such waters be reduced, shall be required to have a permit under this section."],[0,"(g) State administration"],[0,"(1) The Governor of any State desiring to administer its own individual and general permit program for the discharge of dredged or fill material into the navigable waters (other than those waters which are presently used, or are susceptible to use in their natural condition or by reasonable improvement as a means to transport interstate or foreign commerce shoreward to their ordinary high water mark, including all waters which are subject to the ebb and flow of the tide shoreward to their mean high water mark, or mean higher high water mark on the west coast, including wetlands adjacent thereto) within its jurisdiction may submit to the Administrator a full and complete description of the program it proposes to establish and administer under State law or under an interstate compact. In addition, such State shall submit a statement from the attorney general (or the attorney for those State agencies which have independent legal counsel), or from the chief legal officer in the case of an interstate agency, that the laws of such State, or the interstate compact, as the case may be, provide adequate authority to carry out the described program."],[0,"(2) Not later than the tenth day after the date of the receipt of the program and statement submitted by any State under paragraph (1) of this subsection, the Administrator shall provide copies of such program and statement to the Secretary and the Secretary of the Interior, acting through the Director of the United States Fish and Wildlife Service."],[0,"(3) Not later than the ninetieth day after the date of the receipt by the Administrator of the program and statement submitted by any State, under paragraph (1) of this subsection, the Secretary and the Secretary of the Interior, acting through the Director of the United States Fish and Wildlife Service, shall submit any comments with respect to such program and statement to the Administrator in writing."],[0,"(h) Determination of State's authority to issue permits under State program; approval; notification; transfers to State program"],[0,"(1) Not later than the one-hundred-twentieth day after the date of the receipt by the Administrator of a program and statement submitted by any State under paragraph (1) of this subsection, the Administrator shall determine, taking into account any comments submitted by the Secretary and the Secretary of the Interior, acting through the Director of the United States Fish and Wildlife Service, pursuant to subsection (g) of this section, whether such State has the following authority with respect to the issuance of permits pursuant to such program:"],[1,"(A) To issue permits which—"],[2,"(i) apply, and assure compliance with, any applicable requirements of this section, including, but not limited to, the guidelines established under subsection (b)(1) of this section, and sections 1317 and 1343 of this title;"],[2,"(ii) are for fixed terms not exceeding five years; and"],[2,"(iii) can be terminated or modified for cause including, but not limited to, the following:"],[3,"(I) violation of any condition of the permit;"],[3,"(II) obtaining a permit by misrepresentation, or failure to disclose fully all relevant facts;"],[3,"(III) change in any condition that requires either a temporary or permanent reduction or elimination of the permitted discharge."],[1,"(B) To issue permits which apply, and assure compliance with, all applicable requirements of section 1318 of this title, or to inspect, monitor, enter, and require reports to at least the same extent as required in section 1318 of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1344?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1344. Permits for dredged or fill material","tname":"Navigation and Navigable Waters","by":{"0":"2, 3, 51, 52, 3, 3, 3, 3, 4, 4"}},{"t":"usc","label":"33 U.S.C. § 1362","url":"https://www.law.cornell.edu/uscode/text/33/1362","subs":["(6)","(7)","(12)"],"stext":{"head":"§1362. Definitions","paras":[[0,"Except as otherwise specifically provided, when used in this chapter:"],[0,"(1) The term \"State water pollution control agency\" means the State agency designated by the Governor having responsibility for enforcing State laws relating to the abatement of pollution."],[0,"(2) The term \"interstate agency\" means an agency of two or more States established by or pursuant to an agreement or compact approved by the Congress, or any other agency of two or more States, having substantial powers or duties pertaining to the control of pollution as determined and approved by the Administrator."],[0,"(3) The term \"State\" means a State, the District of Columbia, the Commonwealth of Puerto Rico, the Virgin Islands, Guam, American Samoa, the Commonwealth of the Northern Mariana Islands, and the Trust Territory of the Pacific Islands."],[0,"(4) The term \"municipality\" means a city, town, borough, county, parish, district, association, or other public body created by or pursuant to State law and having jurisdiction over disposal of sewage, industrial wastes, or other wastes, or an Indian tribe or an authorized Indian tribal organization, or a designated and approved management agency under section 1288 of this title."],[0,"(5) The term \"person\" means an individual, corporation, partnership, association, State, municipality, commission, or political subdivision of a State, or any interstate body."],[0,"(6) The term \"pollutant\" means dredged spoil, solid waste, incinerator residue, sewage, garbage, sewage sludge, munitions, chemical wastes, biological materials, radioactive materials, heat, wrecked or discarded equipment, rock, sand, cellar dirt and industrial, municipal, and agricultural waste discharged into water. This term does not mean (A) \"sewage from vessels or a discharge incidental to the normal operation of a vessel of the Armed Forces\" within the meaning of section 1322 of this title; or (B) water, gas, or other material which is injected into a well to facilitate production of oil or gas, or water derived in association with oil or gas production and disposed of in a well, if the well used either to facilitate production or for disposal purposes is approved by authority of the State in which the well is located, and if such State determines that such injection or disposal will not result in the degradation of ground or surface water resources."],[0,"(7) The term \"navigable waters\" means the waters of the United States, including the territorial seas."],[0,"(8) The term \"territorial seas\" means the belt of the seas measured from the line of ordinary low water along that portion of the coast which is in direct contact with the open sea and the line marking the seaward limit of inland waters, and extending seaward a distance of three miles."],[0,"(9) The term \"contiguous zone\" means the entire zone established or to be established by the United States under article 24 of the Convention of the Territorial Sea and the Contiguous Zone."],[0,"(10) The term \"ocean\" means any portion of the high seas beyond the contiguous zone."],[0,"(11) The term \"effluent limitation\" means any restriction established by a State or the Administrator on quantities, rates, and concentrations of chemical, physical, biological, and other constituents which are discharged from point sources into navigable waters, the waters of the contiguous zone, or the ocean, including schedules of compliance."],[0,"(12) The term \"discharge of a pollutant\" and the term \"discharge of pollutants\" each means (A) any addition of any pollutant to navigable waters from any point source, (B) any addition of any pollutant to the waters of the contiguous zone or the ocean from any point source other than a vessel or other floating craft."],[0,"(13) The term \"toxic pollutant\" means those pollutants, or combinations of pollutants, including disease-causing agents, which after discharge and upon exposure, ingestion, inhalation or assimilation into any organism, either directly from the environment or indirectly by ingestion through food chains, will, on the basis of information available to the Administrator, cause death, disease, behavioral abnormalities, cancer, genetic mutations, physiological malfunctions (including malfunctions in reproduction) or physical deformations, in such organisms or their offspring."],[0,"(14) The term \"point source\" means any discernible, confined and discrete conveyance, including but not limited to any pipe, ditch, channel, tunnel, conduit, well, discrete fissure, container, rolling stock, concentrated animal feeding operation, or vessel or other floating craft, from which pollutants are or may be discharged. This term does not include agricultural stormwater discharges and return flows from irrigated agriculture."],[0,"(15) The term \"biological monitoring\" shall mean the determination of the effects on aquatic life, including accumulation of pollutants in tissue, in receiving waters due to the discharge of pollutants (A) by techniques and procedures, including sampling of organisms representative of appropriate levels of the food chain appropriate to the volume and the physical, chemical, and biological characteristics of the effluent, and (B) at appropriate frequencies and locations."],[0,"(16) The term \"discharge\" when used without qualification includes a discharge of a pollutant, and a discharge of pollutants."],[0,"(17) The term \"schedule of compliance\" means a schedule of remedial measures including an enforceable sequence of actions or operations leading to compliance with an effluent limitation, other limitation, prohibition, or standard."],[0,"(18) The term \"industrial user\" means those industries identified in the Standard Industrial Classification Manual, Bureau of the Budget, 1967, as amended and supplemented, under the category of \"Division D—Manufacturing\" and such other classes of significant waste producers as, by regulation, the Administrator deems appropriate."],[0,"(19) The term \"pollution\" means the man-made or man-induced alteration of the chemical, physical, biological, and radiological integrity of water."],[0,"(20) The term \"medical waste\" means isolation wastes; infectious agents; human blood and blood products; pathological wastes; sharps; body parts; contaminated bedding; surgical wastes and potentially contaminated laboratory wastes; dialysis wastes; and such additional medical items as the Administrator shall prescribe by regulation."],[0,"(21) Coastal recreation waters.—"],[1,"(A) In general.—The term \"coastal recreation waters\" means—"],[2,"(i) the Great Lakes; and"],[2,"(ii) marine coastal waters (including coastal estuaries) that are designated under section 1313(c) of this title by a State for use for swimming, bathing, surfing, or similar water contact activities."],[1,"(B) Exclusions.—The term \"coastal recreation waters\" does not include—"],[2,"(i) inland waters; or"],[2,"(ii) waters upstream of the mouth of a river or stream having an unimpaired natural connection with the open sea."],[0,"(22) Floatable material.—"],[1,"(A) In general.—The term \"floatable material\" means any foreign matter that may float or remain suspended in the water column."],[1,"(B) Inclusions.—The term \"floatable material\" includes—"],[2,"(i) plastic;"],[2,"(ii) aluminum cans;"],[2,"(iii) wood products;"],[2,"(iv) bottles; and"],[2,"(v) paper products."],[0,"(23) Pathogen indicator.—The term \"pathogen indicator\" means a substance that indicates the potential for human infectious disease."],[0,"(24) Oil and gas exploration and production.—The term \"oil and gas exploration, production, processing, or treatment operations or transmission facilities\" means all field activities or operations associated with exploration, production, processing, or treatment operations, or transmission facilities, including activities necessary to prepare a site for drilling and for the movement and placement of drilling equipment, whether or not such field activities or operations may be considered to be construction activities."],[0,"(25) Recreational vessel.—"],[1,"(A) In general.—The term \"recreational vessel\" means any vessel that is—"],[2,"(i) manufactured or used primarily for pleasure; or"],[2,"(ii) leased, rented, or chartered to a person for the pleasure of that person."],[1,"(B) Exclusion.—The term \"recreational vessel\" does not include a vessel that is subject to Coast Guard inspection and that—"],[2,"(i) is engaged in commercial use; or"],[2,"(ii) carries paying passengers."],[0,"(26) Treatment works.—The term \"treatment works\" has the meaning given the term in section 1292 of this title."],[0,"(27) Green infrastructure.—The term \"green infrastructure\" means the range of measures that use plant or soil systems, permeable pavement or other permeable surfaces or substrates, stormwater harvest and reuse, or landscaping to store, infiltrate, or evapotranspirate stormwater and reduce flows to sewer systems or to surface waters."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1362?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1362. Definitions","tname":"Navigation and Navigable Waters","by":{"0":"2, 2, 2"}},{"t":"usc","label":"42 U.S.C. § 9613","url":"https://www.law.cornell.edu/uscode/text/42/9613","subs":["(h)"],"by":{"0":"41"}},{"t":"usc","label":"28 U.S.C. § 2462","url":"https://www.law.cornell.edu/uscode/text/28/2462","by":{"0":"8, 50"}},{"t":"reg","label":"16 C.F.R. § 1115.20","url":"https://www.ecfr.gov/current/title-16/section-1115.20","by":{"0":"20"}},{"t":"rule","label":"Fed. R. Civ. P. 13","url":"https://www.law.cornell.edu/rules/frcp/rule_13","by":{"0":"37"}},{"t":"reg","label":"72 Fed. Reg. 11,092","url":"https://www.govinfo.gov/link/fr/72/11092","by":{"0":"3"}}]};